SELECT * FROM (SELECT REGIST_SEQNO AS registSeqno, REGIST_BANK_CODE AS registBankCode, ISSUE_PARTY_ID AS issuePartyId, POS_DATE AS posDate, PLAN_ASSET_ID AS planAssetId, ASSET_CODE AS assetCode, TOTAL_NUM AS totalNum, ISSUE_AMT AS issueAmt, UNINVEST_CASH AS uninvestCash, POS_NUM AS posNum, POS_AMT AS posAmt, SEND_STATUS AS sendStatus, CHB_SUBMIT_DEADLINE AS chbSubmitDeadline, SUBMIT_DEADLINE AS submitDeadline, SUBMIT_TIME AS submitTime, SUMIT_SEQ AS sumitSeq, SUBMIT_FEEDBACK_STATUS AS submitFeedbackStatus, STATUS AS status, STATUS_DATE AS statusDate, ORG_CODE AS orgCode, DEPT_CODE AS deptCode, CREATE_USER AS createUser, CREATE_DEPT AS createDept, CREATE_TIME AS createTime, UPDATE_USER AS updateUser, UPDATE_TIME AS updateTime, ROW_NUMBER() OVER(PARTITION BY concat_ws('',POS_DATE,ASSET_CODE) ORDER BY UPDATE_TIME DESC) RANK FROM CHB_BOT_AST_POS_SUB
POS_DATE = #{item.posDate,jdbcType=DATE} AND ASSET_CODE = #{item.assetCode,jdbcType=VARCHAR} AND PLAN_ASSET_ID = #{item.planAssetId,jdbcType=VARCHAR} AND SEND_STATUS in ('02','03')
) WHERE RANK = 1

